<?php // Included only for writable school administrators. ?>
<details class="card card-body mb-3 no-print" open><summary class="fw-bold">Weekly routine profile — automatic or manual</summary>
<p class="small text-muted mt-2">Set period counts, times and breaks for each day. In manual mode, select each subject and its assigned teacher. Period 1 keeps the class teacher; its time and their subject can be edited. Save a profile for later, or activate it to replace the current timetable. Draft profiles may overlap other classes; activation checks all teacher times.</p>
<form method="POST" id="routineProfileForm" data-routine-editor>
<input type="hidden" name="action" value="save_profile"><input type="hidden" name="class_id" value="<?= $class_id ?>"><input type="hidden" name="profile_id" value="<?= $selectedProfile['id']??0 ?>"><input type="hidden" name="revision" value="<?= $selectedProfile['revision']??0 ?>">
<div class="row g-3 mb-3"><div class="col-md-6"><label class="form-label" for="routineProfileName">Profile name</label><input id="routineProfileName" class="form-control" name="name" maxlength="100" value="<?= sanitize($editorName) ?>" placeholder="e.g. Summer 2083, Winter 2083" required></div><div class="col-md-6"><label class="form-label" for="routineMode">Edit mode</label><select name="mode" id="routineMode" class="form-select"><option value="manual" <?= $editorMode==='manual'?'selected':'' ?>>Manual — edit every day / period</option><option value="automatic" <?= $editorMode==='automatic'?'selected':'' ?>>Automatic — use weekly subject requirements</option></select></div></div>
<?php foreach($days as $d=>$name):$settings=$editorLayout[$d];$extra=routineDefaultLayout(10)[$d]; ?>
<details class="border rounded p-3 mb-3 routine-day" data-day="<?= $d ?>" <?= $d===$day?'open':'' ?>><summary class="fw-bold"><?= $name ?></summary>
<div class="row g-3 my-2"><div class="col-md-2"><label class="form-label">Number of periods<select class="form-select routine-count" name="layout[<?= $d ?>][count]" aria-label="<?= $name ?> number of periods"><?php for($n=1;$n<=10;$n++): ?><option value="<?= $n ?>" <?= $settings['count']===$n?'selected':'' ?>><?= $n ?></option><?php endfor; ?></select></label></div>
<?php foreach(['short'=>'Short break','tiffin'=>'Tiffin / long break'] as $kind=>$label): ?><div class="col-md-5"><fieldset><legend class="fs-6"><?= $label ?> (optional)</legend><div class="d-flex gap-2"><label>Start<input type="time" class="form-control" name="layout[<?= $d ?>][breaks][<?= $kind ?>][start]" value="<?= sanitize($settings['breaks'][$kind]['start']) ?>"></label><label>End<input type="time" class="form-control" name="layout[<?= $d ?>][breaks][<?= $kind ?>][end]" value="<?= sanitize($settings['breaks'][$kind]['end']) ?>"></label></div></fieldset></div><?php endforeach; ?></div>
<div class="table-responsive"><table class="table"><thead><tr><th>Period</th><th>Start</th><th>End</th><th class="routine-manual">Subject</th><th class="routine-manual">Teacher</th></tr></thead><tbody>
<?php for($p=1;$p<=10;$p++):$cell=$editorGrid[$d][$p]??[];$time=$settings['times'][$p]??$extra['times'][$p]; ?>
<tr data-period="<?= $p ?>" <?= $p>$settings['count']?'hidden':'' ?>><th><?= $p ?><?= $p===1?' (Class teacher)':'' ?></th><td><input type="time" class="form-control" aria-label="<?= $name ?> period <?= $p ?> start" name="layout[<?= $d ?>][times][<?= $p ?>][start]" value="<?= sanitize($time['start']) ?>" required></td><td><input type="time" class="form-control" aria-label="<?= $name ?> period <?= $p ?> end" name="layout[<?= $d ?>][times][<?= $p ?>][end]" value="<?= sanitize($time['end']) ?>" required></td>
<td class="routine-manual"><select class="form-select routine-subject" aria-label="<?= $name ?> period <?= $p ?> subject" name="grid[<?= $d ?>][<?= $p ?>][subject_id]"><option value="">Free period</option><?php foreach($unique as $s):$assigned=$subjectTeachers[$s['subject_id']]??[];if($p===1&&!in_array((int)$class['class_teacher_id'],$assigned,true))continue; ?><option value="<?= $s['subject_id'] ?>" data-teachers="<?= sanitize(json_encode($assigned)) ?>" <?= ($cell['subject_id']??0)==$s['subject_id']?'selected':'' ?>><?= sanitize($s['name_en']) ?></option><?php endforeach; ?></select></td>
<td class="routine-manual"><select class="form-select routine-teacher" aria-label="<?= $name ?> period <?= $p ?> teacher" name="grid[<?= $d ?>][<?= $p ?>][teacher_id]"><option value="">No teacher</option><?php foreach($teachers as $t):if($p===1&&(int)$t['id']!==(int)$class['class_teacher_id'])continue; ?><option value="<?= $t['id'] ?>" <?= ($cell['teacher_id']??($p===1?$class['class_teacher_id']:0))==$t['id']?'selected':'' ?>>(<?= sanitize(routineTeacherInitials($t['full_name'])) ?>) <?= sanitize($t['full_name']) ?></option><?php endforeach; ?></select></td></tr>
<?php endfor; ?></tbody></table></div></details><?php endforeach; ?>
<div class="row g-3"><div class="col-md-5"><label class="form-label" for="routinePassword">Current administrator password</label><input id="routinePassword" class="form-control" type="password" name="password" autocomplete="current-password" required></div><div class="col-md-7 align-self-end d-flex gap-2 flex-wrap"><button class="btn btn-outline-primary" name="intent" value="save">Save profile only</button><button class="btn btn-primary" name="intent" value="activate" data-confirm-activation>Save &amp; activate</button><?php if($selectedProfile): ?><button class="btn btn-outline-secondary" name="save_as_new" value="1">Save as new profile</button><?php endif; ?></div></div>
</form></details>
